// EN: A loop that runs n times does n steps: Θ(n).
for (let i = 0; i < n; i++) work();

// EN: Each pair (i, j) with i < j is visited once: n(n-1)/2 times, so Θ(n²).
// For n = 10 that is 10 * 9 / 2 = 45 times.
for (let i = 0; i < n; i++)
	for (let j = i + 1; j < n; j++) work();

// EN: i doubles: 1, 2, 4, 8... only about log2(n) iterations: Θ(log n).
for (let i = 1; i < n; i *= 2) work();

// EN: Outer i doubles, inner runs i times: 1 + 2 + 4 + ... + n is about 2n: Θ(n).
for (let i = 1; i < n; i *= 2)
	for (let j = 0; j < i; j++) work();

// EN: Inner loop jumps by i: n/1 + n/2 + n/3 + ... is about n log n: Θ(n log n).
for (let i = 1; i <= n; i++)
	for (let j = 0; j < n; j += i) work();

// EN: Invariant: when the test i < n runs, s is the sum of a[0..i-1].
// Start: i = 0, s = 0 (empty sum). Keep: adding a[i] gives the sum of a[0..i].
// End: i = n, so s is the sum of the whole array.
let s = 0;
for (let i = 0; i < a.length; i++) s += a[i];

// EN: Each call waits for the next one, so n frames pile up: O(n) space.
// (Without tail-call optimisation, which most languages do not guarantee.)
function sum(n: number): number {
	if (n === 0) return 0;
	return n + sum(n - 1);
}
